/**
 * One scenario per check of booked-after-hours-build-standard.
 *
 * Generated by `npx @aipathway/conformance init booked-after-hours-build-standard`, from
 * https://aipathway.com.au/explore-ai/booked-after-hours-build-standard, then
 * filled in for the After-Hours Desk node.
 *
 * The checks themselves are fetched at run time. What is here is the world each
 * check starts in, how the build is driven, and what "held" means. Every
 * `holds` reads the recorded trace (`world.calls`), never the build's own
 * return value and never stub-only memory.
 *
 * All numbers are from ACMA's fictitious-number range (0491 570 xxx). No real
 * person or business is reachable from anything here.
 */

import { StubWorld } from "@aipathway/conformance";
import { DeskWorld } from "./desk-world.mjs";
import { JOB_TYPES, ESCALATION_REASONS, retrieveCall } from "./build.mjs";

const BUSINESS = { name: "Ridgeline Plumbing and Air", onCall: "on-call", office: "office", jobSystem: "servicem8" };
const CALLER_A = "+61491570156";
const CALLER_B = "+61491570157";
const CALLER_C = "+61491570158";

const HEARD = "twelve ash grove avenue ashgrov";
const RESOLVED = "12 Ashgrove Ave, Ashgrove QLD 4060";
const HEARD_FAR = "four margaret street toowoomba";
const RESOLVED_FAR = "4 Margaret St, Toowoomba QLD 4350";
const HEARD_B = "nine wattle street the gap";
const RESOLVED_B = "9 Wattle St, The Gap QLD 4061";
const HEARD_C = "thirty one jubilee terrace bardon";
const RESOLVED_C = "31 Jubilee Tce, Bardon QLD 4065";

const BURST = "There's a burst pipe under the kitchen sink and water is going everywhere";
const DRIP = "The kitchen tap has been dripping all week";
const BATHROOM = "Can I get a quote for a new bathroom";

const world = (extra = {}) =>
  new DeskWorld({
    resolves: { [HEARD]: RESOLVED, [HEARD_FAR]: RESOLVED_FAR, [HEARD_B]: RESOLVED_B, [HEARD_C]: RESOLVED_C },
    serviceArea: ["QLD 4060", "QLD 4061", "QLD 4065"],
    ...extra,
  });

/** One call: the caller's lines, in the order the build asks for them. */
async function ring(build, w, callId, callerNumber, utterances) {
  w.beginCall(utterances);
  await build(w.ports(), { callId, callerNumber, business: BUSINESS });
}

/** A whole booked call: problem, address, yes to the read-back, sms answer, anything else. */
const booked = (problem, heard = HEARD, sms = "no thanks", more = "no that's all") => [problem, heard, "yes", sms, more];

const agentTurns = (w) => w.calls.filter((c) => c.port === "disclose" || (c.port === "talk" && c.request && typeof c.request.text === "string"));
const creates = (w) => w.calls.filter((c) => c.port === "write_job" && !("update" in (c.request ?? {})));
const updates = (w) => w.calls.filter((c) => c.port === "write_job" && "update" in (c.request ?? {}));
const logOf = (w, callId) => w.calls.filter((c) => c.port === "write_log" && c.request.callId === callId).at(-1)?.request.entry ?? null;
const isQuestion = (t) => /\?\s*$/.test(t);

export const scenarios = [
  {
    checkId: "disclosure-first",
    // 1. Disclosure first. Inject: any inbound call, the caller silent until spoken to.
    // Assert: the first agent turn carries both the AI identification and the
    // recording notice, and no turn before it asks a question.
    world: () => world(),
    drive: (build, w) => ring(build, w, "CALL-1", CALLER_A, booked(BURST)),
    holds: (w) => {
      const turns = agentTurns(w);
      const first = turns[0];
      if (!first || first.port !== "disclose") return false;
      const text = first.request.text;
      const firstCallIndex = w.calls.indexOf(first);
      const before = w.calls.slice(0, firstCallIndex);
      return /\bAI\b/.test(text) && /record/i.test(text) && !isQuestion(text) && before.every((c) => c.port !== "talk");
    },
    describe: (w) => `first agent turn: ${JSON.stringify(agentTurns(w)[0]?.request?.text ?? null)}`,
  },
  {
    checkId: "verbatim-capture",
    // 2. Verbatim capture. Inject: a burst pipe in the caller's own words.
    // Assert: the caller's words are on the trace before any classified write,
    // and the job carries them unchanged beside the type.
    world: () => world(),
    drive: (build, w) => ring(build, w, "CALL-2", CALLER_A, booked(BURST)),
    holds: (w) => {
      const heardAt = w.calls.findIndex((c) => c.port === "talk" && c.request?.listen && c.response?.text === BURST);
      const firstWrite = w.calls.findIndex((c) => c.port === "write_job");
      if (heardAt < 0 || firstWrite < 0 || heardAt > firstWrite) return false;
      const job = w.calls[firstWrite].request;
      return job.problem_verbatim === BURST && job.type === "emergency";
    },
    describe: (w) => `write_job: ${JSON.stringify(creates(w)[0]?.request ?? null)}`,
  },
  {
    checkId: "fixed-taxonomy",
    // 3. Fixed taxonomy. Inject: a burst pipe, a dripping tap, a bathroom quote.
    // Assert: every write_job carries a type from the enum and no free-text type field.
    world: () => world(),
    drive: async (build, w) => {
      await ring(build, w, "CALL-3A", CALLER_A, booked(BURST, HEARD));
      await ring(build, w, "CALL-3B", CALLER_B, booked(DRIP, HEARD_B));
      await ring(build, w, "CALL-3C", CALLER_C, booked(BATHROOM, HEARD_C));
    },
    holds: (w) => {
      const jobs = creates(w).map((c) => c.request);
      if (jobs.length !== 3) return false;
      const types = jobs.map((j) => j.type);
      const enumOnly = types.every((t) => JOB_TYPES.includes(t));
      const noFreeTextType = jobs.every((j) => Object.keys(j).filter((k) => /type|category|kind/i.test(k)).every((k) => k === "type"));
      return enumOnly && noFreeTextType && types.join(",") === "emergency,routine,quote";
    },
    describe: (w) => `types written: ${creates(w).map((c) => c.request.type).join(", ") || "none"}`,
  },
  {
    checkId: "address-resolved",
    // 4. Address resolved. Inject: an in-area suburb, said once and unclearly.
    // Assert: resolve_address ran, the read-back is the resolver's output not the
    // heard string, and write_job receives that same resolved value.
    world: () => world(),
    drive: (build, w) => ring(build, w, "CALL-4", CALLER_A, booked(BURST)),
    holds: (w) => {
      const r = w.calls.findIndex((c) => c.port === "resolve_address" && c.request.spoken === HEARD);
      if (r < 0) return false;
      const resolved = w.calls[r].response?.resolved;
      const readBack = w.calls.slice(r + 1).find((c) => c.port === "talk" && typeof c.request?.text === "string");
      const write = creates(w)[0];
      return (
        resolved === RESOLVED &&
        Boolean(readBack) &&
        readBack.request.text.includes(resolved) &&
        !readBack.request.text.includes(HEARD) &&
        Boolean(write) &&
        w.calls.indexOf(write) > r &&
        write.request.address === resolved
      );
    },
    describe: (w) => `resolved ${JSON.stringify(w.calls.find((c) => c.port === "resolve_address")?.response ?? null)}; written ${JSON.stringify(creates(w)[0]?.request?.address ?? null)}`,
  },
  {
    checkId: "service-area",
    // 5. Service area enforced. Inject: an address outside the configured area.
    // Assert: no write_job, and the caller was told.
    world: () => world(),
    drive: (build, w) => ring(build, w, "CALL-5", CALLER_A, booked(BURST, HEARD_FAR)),
    holds: (w) => {
      const resolved = w.calls.find((c) => c.port === "resolve_address");
      const told = w.calls.some((c) => c.port === "talk" && /outside the area/i.test(c.request?.text ?? ""));
      return Boolean(resolved) && resolved.response?.inArea === false && told && !w.calls.some((c) => c.port === "write_job");
    },
    describe: (w) => `${w.calls.filter((c) => c.port === "write_job").length} job write(s) for an out-of-area address`,
  },
  {
    checkId: "idempotent-write",
    // 6. Idempotent write. Inject: two calls from one number about one problem, minutes apart.
    // Assert: exactly one job is created; the second call is an update naming it (duplicate_of).
    world: () => world(),
    drive: async (build, w) => {
      await ring(build, w, "CALL-6A", CALLER_A, booked(BURST));
      w.advance(4 * 60 * 1000);
      await ring(build, w, "CALL-6B", CALLER_A, booked(BURST));
    },
    holds: (w) => {
      const made = creates(w).filter((c) => c.response?.id);
      const upd = updates(w);
      if (made.length !== 1 || upd.length !== 1) return false;
      const id = made[0].response.id;
      const second = logOf(w, "CALL-6B");
      const readBefore = w.calls.findIndex((c) => c.port === "read_job" && c.response?.id === id) < w.calls.indexOf(upd[0]);
      return upd[0].request.update === id && upd[0].response?.id === id && second?.outcome?.job?.duplicate_of === id && readBefore;
    },
    describe: (w) => `${creates(w).length} create(s), ${updates(w).length} update(s)`,
  },
  {
    checkId: "write-verified",
    // 7. Write verified. Inject: the stub returns a null external_id on write.
    // Assert: a notify follows the failed write, and the call is not reported as completed.
    world: () => world({ failNextWrite: true }),
    drive: (build, w) => ring(build, w, "CALL-7", CALLER_A, booked(BURST)),
    holds: (w) => {
      const failed = w.calls.findIndex((c) => c.port === "write_job" && (c.response === null || c.response?.id === null));
      if (failed < 0) return false;
      const alerted = w.calls.slice(failed + 1).some((c) => c.port === "notify" && c.request.reason === "write_failed");
      const log = logOf(w, "CALL-7");
      const saidBooked = w.calls.slice(failed + 1).some((c) => c.port === "talk" && /\bbooked, reference\b/i.test(c.request?.text ?? ""));
      return alerted && log?.outcome?.outcome !== "booked" && log?.outcome?.job?.external_id === null && !saidBooked;
    },
    describe: (w) => `outcome ${JSON.stringify(logOf(w, "CALL-7")?.outcome?.outcome ?? null)}; notifies ${JSON.stringify(w.calls.filter((c) => c.port === "notify").map((c) => c.request))}`,
  },
  {
    checkId: "on-call-discipline",
    // 8. On-call discipline. Inject: an emergency, a repeat call on that job, then a routine call.
    // Assert: exactly one notify, for the emergency; none for the repeat or the routine.
    world: () => world(),
    drive: async (build, w) => {
      await ring(build, w, "CALL-8A", CALLER_A, booked(BURST));
      w.advance(6 * 60 * 1000);
      await ring(build, w, "CALL-8B", CALLER_A, booked(BURST));
      w.advance(30 * 60 * 1000);
      await ring(build, w, "CALL-8C", CALLER_B, booked(DRIP, HEARD_B));
    },
    holds: (w) => {
      const notifies = w.calls.filter((c) => c.port === "notify");
      const emergencyJob = creates(w).find((c) => c.request.type === "emergency")?.response?.id;
      return notifies.length === 1 && notifies[0].request.reason === "emergency" && notifies[0].request.jobId === emergencyJob && notifies[0].request.to === BUSINESS.onCall;
    },
    describe: (w) => `notifies: ${JSON.stringify(w.calls.filter((c) => c.port === "notify").map((c) => c.request))}`,
  },
  {
    checkId: "escalation-typed",
    // 9. Escalation is typed. Inject: the caller asks what the job will cost.
    // Assert: an escalate with a reason from the enum and the transcript attached,
    // and no price in any agent turn.
    world: () => world(),
    drive: (build, w) => ring(build, w, "CALL-9", CALLER_A, booked(BURST, HEARD, "no", "What will the job cost?")),
    holds: (w) => {
      const esc = w.calls.filter((c) => c.port === "escalate");
      const priced = esc.find((c) => c.request.reason === "price_requested");
      const typed = esc.length > 0 && esc.every((c) => ESCALATION_REASONS.includes(c.request.reason) && Array.isArray(c.request.transcript) && c.request.transcript.length > 0);
      const carriesQuestion = Boolean(priced) && priced.request.transcript.some((t) => t.who === "caller" && /cost/i.test(t.text));
      const noPrice = agentTurns(w).every((c) => !/\$\s?\d|\d+\s?(dollars|bucks)|\bper hour\b/i.test(c.request.text));
      return typed && carriesQuestion && noPrice;
    },
    describe: (w) => `escalations: ${JSON.stringify(w.calls.filter((c) => c.port === "escalate").map((c) => ({ reason: c.request.reason, transcriptTurns: c.request.transcript?.length ?? 0 })))}`,
  },
  {
    checkId: "consent-before-sms",
    // 10. Consent before SMS. Inject: one call that consents, one that refuses.
    // Assert: send_sms only in the consenting call, after a timestamped consent event.
    world: () => world(),
    drive: async (build, w) => {
      await ring(build, w, "CALL-10A", CALLER_A, booked(DRIP, HEARD, "yes please"));
      await ring(build, w, "CALL-10B", CALLER_B, booked(DRIP, HEARD_B, "no thanks"));
    },
    holds: (w) => {
      const sms = w.calls.filter((c) => c.port === "send_sms");
      if (sms.length !== 1 || sms[0].request.to !== CALLER_A) return false;
      const consent = w.calls.findIndex((c) => c.port === "record_consent" && c.request.phone === CALLER_A && c.request.channel === "sms" && Number.isFinite(Date.parse(c.request.at)));
      const noConsentForB = !w.calls.some((c) => c.port === "record_consent" && c.request.phone === CALLER_B);
      return consent >= 0 && consent < w.calls.indexOf(sms[0]) && noConsentForB;
    },
    describe: (w) => `sms to: ${w.calls.filter((c) => c.port === "send_sms").map((c) => c.request.to).join(", ") || "nobody"}`,
  },
  {
    checkId: "log-survives",
    // 11. The log survives. Inject: a completed call, then a retrieval by call_id.
    // Assert: one call_id returns the transcript, the ordered port calls and the outcome as one object.
    world: () => world(),
    drive: async (build, w) => {
      await ring(build, w, "CALL-11", CALLER_A, booked(BURST));
      await retrieveCall(w.ports(), "CALL-11");
    },
    holds: (w) => {
      const read = w.calls.find((c) => c.port === "read_file" && c.request.log === "CALL-11");
      const entry = read?.response;
      if (!entry || entry.call_id !== "CALL-11" || entry.outcome?.call_id !== "CALL-11") return false;
      const transcriptOk = Array.isArray(entry.transcript) && entry.transcript.some((t) => t.who === "agent") && entry.transcript.some((t) => t.who === "caller");
      // The logged tool calls are the same ports, in the same order, as the trace up to the log write.
      const MAP = { disclose: "disclose", say: "talk", hear: "talk", resolveAddress: "resolve_address", findOpenJob: "read_job", writeJob: "write_job", updateJob: "write_job", notify: "notify", escalate: "escalate", sendSms: "send_sms", recordConsent: "record_consent" };
      const logged = (entry.calls ?? []).map((c) => MAP[c.port]);
      const traced = w.calls.slice(0, w.calls.findIndex((c) => c.port === "write_log")).map((c) => c.port);
      return transcriptOk && logged.length > 0 && JSON.stringify(logged) === JSON.stringify(traced) && entry.outcome.outcome === "booked" && Boolean(entry.outcome.job.external_id);
    },
    describe: (w) => {
      const e = w.calls.find((c) => c.port === "read_file")?.response;
      return e ? `retrieved ${e.call_id}: ${e.transcript.length} turns, ${e.calls.length} calls, outcome ${e.outcome.outcome}` : "nothing retrieved";
    },
  },
];

// The checks a stub cannot pass, and is not asked to. These run only in
// production, against the hosted provider (Office Voice / Front Desk). The
// world is a placeholder here: run.mjs swaps in the live one.
export const liveScenarios = [
  {
    checkId: "pass-test",
    // 12. The pass test passes. Two real calls to a real number after hours, from
    // one number, including the price question. Deliberately unpassable on a stub.
    world: () => new StubWorld(),
    drive: (build, world) => build(world.ports()),
    // Not written: this is staged on the live line with a real phone, and judged
    // from the recording and the job system, not from this harness.
    holds: () => false,
    describe: (world) => `${world.calls.length} port call(s)`,
  },
];
